from pathlib import Path
from docx import Document
from docx.shared import Inches, Pt, RGBColor
out=Path('leverans');d=Document();sec=d.sections[0];sec.page_width=Inches(8.5);sec.page_height=Inches(11)
sec.top_margin=sec.bottom_margin=Inches(.7);sec.left_margin=sec.right_margin=Inches(.7)
for name in ['Normal','Title','Subtitle','Heading 1','Heading 2']:
 st=d.styles[name];st.font.name='Calibri';st.font.color.rgb=RGBColor(0,0,0)
d.styles['Normal'].font.size=Pt(11);d.styles['Normal'].paragraph_format.space_after=Pt(8)
d.styles['Title'].font.size=Pt(30);d.styles['Heading 1'].font.size=Pt(21);d.styles['Heading 2'].font.size=Pt(14)
sec.footer.paragraphs[0].text='Börscase 2.1  •  Produktpresentation  •  14 september 2026'
sec.footer.paragraphs[0].style=d.styles['Caption']
def p(t):d.add_paragraph(t)
def h(t):d.add_heading(t,2)
def pic(f,caption):
 d.add_picture(str(out/'skarmbilder'/f),width=Inches(7.05));d.add_paragraph(caption,'Caption')
def page(title):d.add_page_break();d.add_heading(title,1)
d.add_paragraph('Börscase produktpresentation','Title')
p('För dig som vill förstå bolagen bakom aktierna och följa upp dina egna placeringsidéer. Börscase samlar kurser, rapportunderlag och nyckeltal i en lokal app, med länkar till källorna och en journal som bevarar tidigare analyser.')
h('Från bolagssiffror till en tydligare analys')
p('Se hur lönsamheten utvecklas, om vinsten blir kassaflöde och hur värderingen förhåller sig till bolagets resultat. Analysrummet förklarar begreppen där siffrorna visas, så att du kan lägga mer tid på frågorna som avgör ditt case.')
pic('01-kassaflode.png','Atlas Copco A i appen. Utsnitt av kassaflödesmått för helåret 2025, fångat den 14 september 2026. Historiskt exempel, ingen köpbedömning.')
h('En arbetsplats för hela ditt bolagscase')
p('Översikten hjälper dig att jämföra bolag. Analysrummet samlar nyckeltal, förändringar, rapportkällor, bevakningar, värderingsscenarier och din analysjournal. Svenska och amerikanska bolag ingår; tillgången till rapportdata varierar mellan bolagen.')
p('Nyttan är ett mer strukturerat och granskningsbart beslutsunderlag. Appens bolagsrangordning har inte visat någon säker överavkastning i de tester som genomförts.')
page('Multiplar och kassaflöde med förklaringar')
p('P/E, P/B, P/S, EV/EBIT och EV/EBITDA gör det möjligt att belysa värderingen från flera håll. I Analysrummet finns 27 nyckeltal med definitioner, beräkningar och källunderlag när uppgifterna är tillgängliga.')
pic('05-multiplar.png','Apple i Analysrummet. Historisk helårsvinst och sparat börsvärde; siffrorna är ett exempel från appen och ändras med underlaget.')
h('Följ pengarna genom verksamheten')
p('Kassaflöde från rörelsen, investeringar och fritt kassaflöde visar hur verksamheten finansierar sig. Marginaler, nettoskuld och soliditet kompletterar bilden. Utdelningen kan jämföras med både nettovinst och fritt kassaflöde när utdelningsdata finns.')
h('Förstå vad multipeln faktiskt mäter')
p('P/E här bygger på historisk vinst, inte analytikernas prognoser. Du kan välja senaste helår eller rullande tolv månader när fyra sammanhängande kvartal finns. P/B bygger på bokfört eget kapital och är inte ett beräknat substansvärde.')
p('I den äldre branschmodellen används inte P/E för fastighets- och investmentbolag. Analysrummet kan ändå visa ett historiskt P/E från underlaget, med en förklaring om värdeförändringar. Förvaltningsresultat och substansvärde behöver kompletteras från bolagets rapport.')
p('Saknade uppgifter visas öppet. Förlust ger inget positivt P/E, och bankanalysen utesluter vissa olämpliga mått. Organisk tillväxt, orderingång, konsensus och prognos-P/E hämtas inte automatiskt i denna version.')
page('Upptäck förändringar och gå till källan')
p('En ny rapport blir mer användbar när du kan jämföra den med föregående underlag. Börscase visar förändringar mellan bokslut och sparade analyser, med rapportperioder och länkar som hjälper dig att kontrollera uppgifterna.')
pic('02-kallor.png','Apple i vyn Förändringar och källor. Tabellen visar utveckling mellan årsboksluten och länkar till underlaget.')
h('Hitta det som förtjänar en närmare läsning')
p('Rapportanalysen kan lyfta textsignaler och nya eller omskrivna riskstycken när jämförbara rapporter finns. Du kan gå vidare till originalrapporten och bedöma sammanhanget. Textregler hittar signalerna; de är inte en fullständig automatisk granskning av bolaget.')
h('Gör din idé möjlig att följa upp')
p('I Ledning och bevakning kan du dokumentera vad som måste stämma i ditt case och sätta upp mätbara bevakningar. Journalen bevarar tidigare analyser, så att du kan återvända till vad du visste när du gjorde din bedömning.')
page('Pröva värderingen med egna antaganden')
p('Vilken tillväxt och marginal krävs för att motivera priset? Scenariovyn låter dig ändra antaganden om verksamheten och kapitalkostnaden och jämföra ett pessimistiskt, ett grundläggande och ett optimistiskt scenario.')
pic('03-scenarier.png','Scenariovyn med Apples underlag och redigerbara exempelantaganden. Inställningarna illustrerar funktionen och är inga prognoser.')
h('Se hur känslig slutsatsen är')
p('Beräkningen använder fem års kassaflöden och ett terminalvärde. En känslighetstabell visar hur värdet påverkas av marginal och kapitalkostnad. Appen visar också vilken tillväxt dagens pris skulle kräva med övriga antaganden oförändrade.')
p('Resultaten är räkneexempel som beror på dina antaganden. Modellen är förenklad och inte anpassad för banker. Den hjälper dig att pröva ett resonemang, men fastställer inte bolagets rätta värde.')
page('Bygg erfarenhet som går att utvärdera')
p('Analysjournalen ger appen ett minne. Sparade observationer kan följas upp efter 30, 90 och 365 dagar, med jämförelseindex och en schablonkostnad. Det gör det möjligt att undersöka vilka samband som håller över tid.')
pic('04-journal.png','Journal och lärande vid dokumentets tillkomst. Appen väntar ännu på tillräckliga framtida utfall för modellträning.')
h('Lärandet behöver verkliga resultat')
p('Träning kräver minst 120 kompletta observationer från 12 startmånader och 90 dagars facit. En modell utvärderas i tidsordning och kör i skuggläge utan att ändra råden. Detta är en funktion för prövning av modeller, inte ett löfte om att appen automatiskt blir bättre på att välja aktier.')
h('Kom igång på din egen dator')
p('Packa upp ZIP-filen. Med Python 3.10 eller senare installerat kör du INSTALLERA.bat, sedan SKANNA.bat och STARTA_APP.bat. Internet behövs för installation och datahämtning. Appen öppnas i webbläsaren och körs lokalt.')
p('Paketet innehåller kod och startfiler. Din journal, egna bolagsinställningar och hämtade bolagsdata följer inte med. Läs ANALYSRUM.md för handhavande och LICENS.txt för villkor. Nuvarande licens gäller privat, icke kommersiell användning.')
# Remove borders inherited from the bundled Word template.
for node in list(d.styles.element.iter()):
 if node.tag.endswith('}pBdr') and node.getparent() is not None:node.getparent().remove(node)
d.styles['Caption'].font.color.rgb=RGBColor.from_string('555555')
d.styles['Caption'].font.bold=False
d.save(out/'Borscase-produktpresentation.docx')
print('Created',out/'Borscase-produktpresentation.docx')
